import { ts } from "ts-morph";
import type { Redactor } from "../redact";

/**
 * Code-enforced subset of the Test generation rules (spec: Test generation rules). Runs on every
 * generated file before it is saved; any error rejects the write and is sent back to the agent.
 */
export type LintSeverity = "error" | "warning";

export interface LintIssue {
  rule: string;
  severity: LintSeverity;
  /** 1-based line number. */
  line: number;
  message: string;
}

export interface LintContext {
  /** spec: a test file; page-object: no assertions allowed; support: other helpers. */
  kind: "spec" | "page-object" | "support";
  flowSlug?: string;
  role?: string;
  /** Required import line for spec files (existing projects use their own fixtures). */
  testImport?: string;
  redactor?: Redactor;
  /** Absolute base URL of the environment; hardcoding it in goto() is flagged. */
  baseURL?: string;
}

export const HEADER_RE = /^\/\/ Generated by DOMinion from (.+?) \(run ([\w.-]+)\)/;

/** True when a file carries the DOMinion header comment (ownership rule). */
export function hasDominionHeader(content: string): boolean {
  const first = content.split(/\r?\n/).find((line) => line.trim() !== "");
  return first !== undefined && (HEADER_RE.test(first.trim()) || /^\/\/ Generated by DOMinion\b/.test(first.trim()));
}

/** Removes // comments (outside strings) so rules do not fire on commented-out code. */
function stripLineComment(line: string): string {
  let quote: string | undefined;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i]!;
    if (quote) {
      if (ch === "\\") i++;
      else if (ch === quote) quote = undefined;
    } else if (ch === '"' || ch === "'" || ch === "`") {
      quote = ch;
    } else if (ch === "/" && line[i + 1] === "/") {
      return line.slice(0, i);
    }
  }
  return line;
}

interface LineRule {
  rule: string;
  severity: LintSeverity;
  pattern: RegExp;
  message: string;
  kinds?: ReadonlyArray<LintContext["kind"]>;
}

const LINE_RULES: LineRule[] = [
  {
    rule: "no-xpath",
    severity: "error",
    pattern: /xpath=|\blocator\(\s*["'`]\(?\/\//,
    message: "XPath selectors are not allowed. Use getByRole/getByLabel/getByPlaceholder/getByText/getByTestId.",
  },
  {
    rule: "no-wait-for-timeout",
    severity: "error",
    pattern: /\bwaitForTimeout\s*\(/,
    message: "waitForTimeout is not allowed. Wait on a locator or URL with a web-first assertion instead.",
  },
  {
    rule: "no-sleep",
    severity: "error",
    pattern: /(?<![.\w])setTimeout\s*\(|(?<![.\w])sleep\s*\(/,
    message: "Manual sleeps are not allowed. Wait on a locator or URL instead.",
  },
  {
    rule: "no-element-handles",
    severity: "error",
    pattern: /\.\$\$?\(|\.\$\$?eval\s*\(|\belementHandle\b/,
    message: "Element handles ($, $$, $eval) are not allowed. Use locators.",
  },
  {
    rule: "no-dom-position-selectors",
    severity: "error",
    pattern: /:nth-child\(|:nth-of-type\(|:first-child|:last-child|\s>\s*(div|span|li)\b.*["'`]\s*\)/,
    message: "DOM-position CSS selectors are not allowed. Locate by role, label, text or test id, scoped with filter().",
  },
  {
    rule: "no-generated-classes",
    severity: "error",
    pattern: /locator\(\s*["'`][^"'`]*\.(css-[a-z0-9]{4,}|sc-[a-zA-Z]{5,}|jsx-\d+|[A-Za-z][\w-]*_[A-Za-z][\w-]*__[A-Za-z0-9_-]{5,}|_[a-zA-Z0-9]{5,}_\w+)|\[class\*=/,
    message: "Auto-generated class names are not allowed in selectors. Use role, label, text or test id.",
  },
  {
    rule: "web-first-assertions",
    severity: "error",
    pattern: /\bexpect\s*\(\s*await\b/,
    message:
      "Use web-first assertions (await expect(locator).toHaveText(...), toBeVisible(), toHaveCount(), toHaveValue(), toHaveURL()) instead of expect(await ...).",
  },
  {
    rule: "no-only",
    severity: "error",
    pattern: /\b(test|describe)\.only\s*\(|\btest\.describe\.only\s*\(/,
    message: "test.only/describe.only must not be committed.",
  },
  {
    rule: "no-pause",
    severity: "error",
    pattern: /\bpage\.pause\s*\(/,
    message: "page.pause() must not be committed.",
  },
  {
    rule: "no-env-access",
    severity: "error",
    pattern: /\bprocess\s*\.\s*env\b|\bprocess\s*\[/,
    message: "Generated code must not read environment variables; tests start from the saved session and never need credentials.",
  },
  {
    rule: "no-node-builtins",
    severity: "error",
    pattern: /\bfrom\s+["'](node:)?(fs|fs\/promises|child_process|http|https|http2|net|tls|dgram|dns|worker_threads|vm|os|cluster|inspector|module|process)["']|\brequire\s*\(|\bimport\s*\(/,
    message: "Generated code may only import the test framework, the project's fixtures and page objects: no Node built-ins, require() or dynamic import().",
  },
  {
    rule: "no-dynamic-code",
    severity: "error",
    pattern: /\beval\s*\(|\bnew\s+Function\s*\(/,
    message: "eval and new Function are not allowed in generated code.",
  },
  {
    rule: "no-raw-network",
    severity: "error",
    pattern: /(?<![.\w])fetch\s*\(|\b(XMLHttpRequest|WebSocket)\b|\brequest\s*\.\s*(get|post|put|patch|delete|head|fetch)\s*\(\s*["'`]https?:\/\//,
    message: "Generated tests talk to the app only through the browser (or request with relative URLs), never to other hosts.",
  },
  {
    rule: "no-page-scripts",
    severity: "error",
    pattern: /\.(evaluate|evaluateHandle|addInitScript|exposeFunction|exposeBinding|\$eval)\s*\(/,
    message: "Generated tests must not run scripts in the page; use locators and web-first assertions.",
  },
  {
    rule: "no-session-access",
    severity: "error",
    pattern: /\.storageState\s*\(|\.cookies\s*\(|\.auth[\\/]/,
    message: "Generated tests must not read sessions or cookies; they start from the saved session.",
  },
  {
    rule: "no-networkidle",
    severity: "warning",
    pattern: /networkidle/,
    message: "Avoid waiting for networkidle; wait for the element or URL that proves the step finished.",
  },
  {
    rule: "no-force",
    severity: "warning",
    pattern: /force:\s*true/,
    message: "Avoid { force: true }; it hides real actionability problems.",
  },
  {
    rule: "no-assertions-in-page-objects",
    severity: "error",
    pattern: /\bexpect\s*\(/,
    message: "Page objects must not contain assertions; keep expect() in the spec.",
    kinds: ["page-object"],
  },
];

const POSITIONAL_RE = /\.(nth\(|first\(\)|last\(\))/;

export function lintGeneratedFile(content: string, context: LintContext): LintIssue[] {
  const issues: LintIssue[] = [];
  const lines = content.split(/\r?\n/);
  const add = (rule: string, severity: LintSeverity, line: number, message: string) =>
    issues.push({ rule, severity, line, message });

  lines.forEach((rawLine, index) => {
    const code = stripLineComment(rawLine);
    for (const rule of LINE_RULES) {
      if (rule.kinds && !rule.kinds.includes(context.kind)) continue;
      if (rule.pattern.test(code)) add(rule.rule, rule.severity, index + 1, rule.message);
    }
    if (POSITIONAL_RE.test(code)) {
      const previous = lines.slice(0, index).reverse().find((l) => l.trim() !== "") ?? "";
      const commented = rawLine.includes("//") || previous.trim().startsWith("//");
      if (!commented) {
        add(
          "positional-locator-needs-comment",
          "error",
          index + 1,
          "Use .nth()/.first()/.last() only when the plan intends position, and say so in a comment on the same line or the line above.",
        );
      }
    }
    if (context.baseURL && /\.goto\(\s*["'`]https?:\/\//.test(code) && code.includes(new URL(context.baseURL).host)) {
      add("relative-urls", "warning", index + 1, "Use paths relative to baseURL in page.goto(), not the full environment URL.");
    }
  });

  if (context.kind === "spec") {
    const firstLine = lines.findIndex((l) => l.trim() !== "");
    if (firstLine === -1 || !HEADER_RE.test(lines[firstLine]!.trim())) {
      add(
        "header-comment",
        "error",
        Math.max(firstLine, 0) + 1,
        'The file must start with the header comment: // Generated by DOMinion from <plan path> (run <run id>)',
      );
    }
    if (context.testImport) {
      const normalized = (s: string) => s.replace(/\s+/g, " ").replace(/'/g, '"').replace(/;$/, "").trim();
      const present = new Set(lines.map(normalized));
      const required = context.testImport.split(/\r?\n/).map(normalized).filter(Boolean);
      if (!required.every((line) => present.has(line))) {
        add("test-import", "error", 1, `Import test and expect with exactly: ${context.testImport.replace(/\n/g, " ")}`);
      }
    }
    const describe = /\btest\.describe(?:\.serial|\.parallel)?\s*\(\s*(["'`])((?:\\.|(?!\1).)*)\1/.exec(content);
    if (!describe) {
      add("describe-per-flow", "error", 1, "Wrap the flow's tests in one test.describe().");
    } else {
      const title = describe[2]!;
      const required = ["@dominion", ...(context.flowSlug ? [`@flow:${context.flowSlug}`] : []), ...(context.role ? [`@role:${context.role}`] : [])];
      const missing = required.filter((tag) => !new RegExp(`(^|\\s)${tag.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}(\\s|$)`).test(title));
      if (missing.length) {
        const line = content.slice(0, describe.index).split(/\r?\n/).length;
        add("tags", "error", line, `The describe title must include the tags ${missing.join(" ")} (title: "${title}").`);
      }
    }
    if (!/\bexpect\s*\(/.test(content.replace(/\/\/.*$/gm, ""))) {
      add("assert-outcomes", "error", 1, "Every test must assert on meaningful outcomes with expect(); the file has no assertions.");
    }
    if (!/\btest\.step\s*\(/.test(content)) {
      add("test-steps", "warning", 1, "Use test.step() for each plan step, titled with the plan's step wording.");
    }
  }

  const syntax = syntaxError(content);
  if (syntax) add("syntax", "error", syntax.line, `The file does not parse: ${syntax.message}`);

  const leaked = context.redactor?.findSecrets(content) ?? [];
  if (leaked.length) {
    add(
      "no-secrets",
      "error",
      1,
      `The file contains the value of ${leaked.join(", ")}. Never hardcode credentials; generated tests start from the saved session.`,
    );
  }
  return issues.sort((a, b) => a.line - b.line);
}

/** First TypeScript syntax error, if any (transpile-only, no type checking). */
export function syntaxError(content: string): { line: number; message: string } | undefined {
  const result = ts.transpileModule(content, {
    reportDiagnostics: true,
    fileName: "generated.ts",
    compilerOptions: { target: ts.ScriptTarget.ES2022, module: ts.ModuleKind.ESNext },
  });
  const diagnostic = result.diagnostics?.find((d) => d.category === ts.DiagnosticCategory.Error);
  if (!diagnostic) return undefined;
  const line = diagnostic.file && diagnostic.start !== undefined ? diagnostic.file.getLineAndCharacterOfPosition(diagnostic.start).line + 1 : 1;
  return { line, message: ts.flattenDiagnosticMessageText(diagnostic.messageText, " ") };
}

export function lintErrors(issues: readonly LintIssue[]): LintIssue[] {
  return issues.filter((issue) => issue.severity === "error");
}

export function formatLintIssues(file: string, issues: readonly LintIssue[]): string {
  return issues.map((i) => `${file}:${i.line} ${i.severity} [${i.rule}] ${i.message}`).join("\n");
}
